 "content": "def transform(grid):
    """Draw between same-color markers aligned in a separator-defined panel lattice."""
    h, w = len(grid), len(grid[0])
    rs = [r for r in range(h) if sum(v == 8 for v in grid[r]) >= w - 1]
    cs = [c for c in range(w) if sum(grid[r][c] == 8 for r in range(h)) >= h - 1]
    rb, cb = [-1] + rs + [h], [-1] + cs + [w]
    rp = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cp = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    markers = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 8):
                pr = next(i for i, (a,b) in enumerate(rp) if a <= r < b)
                pc = next(i for i, (a,b) in enumerate(cp) if a <= c < b)
                markers.setdefault(v, set()).add((pr, pc))
    strokes = {}
    for color, pts in markers.items():
        pts = sorted(pts)
        for i, (r1,c1) in enumerate(pts):
            for r2,c2 in pts[i+1:]:
                if r1 == r2:
                    for pc in range(min(c1,c2), max(c1,c2)+1): strokes.setdefault((r1,pc),set()).add(color)
                elif c1 == c2:
                    for pr in range(min(r1,r2), max(r1,r2)+1): strokes.setdefault((pr,c1),set()).add(color)
    out = [row[:] for row in grid]
    for (pr,pc), colors in strokes.items():
        value = 6 if len(colors) > 1 else next(iter(colors))
        for r in range(*rp[pr]):
            for c in range(*cp[pc]):
                if grid[r][c] == 0 or grid[r][c] == 8:
                    out[r][c] = value
    return out
